<?php
require_once __DIR__.'/accounting_periods.php';
/** Small public financial signals; private evidence/drafts never enter this projection. */
require_once __DIR__.'/budget_actuals.php';
function dashboard_reporting_status(PDO $pdo,int $uid,string $asof): array
{
    return accounting_read($pdo,function()use($pdo,$uid,$asof){reporting_actor($pdo,$uid);$asof=accounting_date($asof);$cash=null;$advances=null;$pending=0;$setup='Reporting setup needed';$schema=report_configuration_schema($pdo);
        if($schema['state']==='partial')throw new ReportingProblem('Reporting setup needs a deployment integrity review.',503);
        if($schema['complete']){$configuration=report_configuration_current($pdo,substr($asof,0,7).'-01');if($configuration){$tb=accounting_trial_balance($pdo,$asof);if($tb['invalid_journals'])throw new ReportingProblem('Posted balances need an integrity review.',503);$balances=array_column($tb['rows'],null,'CategoryID');$sum=0;foreach($configuration['payload']['cash_accounts'] as $id){if(!isset($balances[$id])||$balances[$id]['Account_Type']!=='Asset')throw new ReportingProblem('Configured cash accounts need an integrity review.',503);$sum=accounting_add($sum,accounting_cents($balances[$id]['net']));}$cash=accounting_decimal($sum);$setup='Configured cash accounts';}}
        if(stage2_schema($pdo)&&stage3_schema($pdo)){$state=advance_state($pdo,$asof);$sum=0;foreach($state['reconciliation'] as $r)if(!$r['ok'])throw new ReportingProblem('Advance control balances need reconciliation.',503);foreach($state['advances'] as $a)$sum=accounting_add($sum,$a['outstanding_cents']);$advances=accounting_decimal($sum);}
        foreach(['trial_balance_snapshots'=>"SELECT COUNT(*) FROM trial_balance_snapshots WHERE review_status='Requested'"] as $table=>$query){$s=$pdo->prepare('SELECT COUNT(*) FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=?');$s->execute([$table]);if((int)$s->fetchColumn())$pending+=(int)$pdo->query($query)->fetchColumn();}
        $budgetSchema=budget_revision_schema($pdo);if($budgetSchema['state']==='partial')throw new ReportingProblem('Budget approvals need an integrity review.',503);if($budgetSchema['complete'])$pending+=(int)$pdo->query('SELECT COUNT(*) FROM budget_revisions r LEFT JOIN budget_review_events e ON e.revision_id=r.id WHERE e.id IS NULL')->fetchColumn();
        $periodSchema=periods_schema($pdo);if($periodSchema['state']==='partial')throw new ReportingProblem('Complete report reviews need an integrity review.',503);if($periodSchema['complete'])$pending+=(int)$pdo->query('SELECT COUNT(*) FROM complete_report_bundles b LEFT JOIN complete_report_reviews r ON r.bundle_id=b.id WHERE r.id IS NULL')->fetchColumn();
        return ['as_of'=>$asof,'cash'=>$cash,'cash_label'=>$setup,'outstanding_advances'=>$advances,'pending_reviews'=>$pending,'cash_is_spendable_claim'=>false];
    });
}
function dashboard_render_reporting(?array $data,?array $budget,string $asof): void
{
    $e=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');$m=static fn($v)=>$v===null?'Unavailable':htmlspecialchars(accounting_money((string)$v),ENT_QUOTES,'UTF-8');
    ?><section class="budget-status-panel" aria-label="Current accounting and approval status"><h2>Current accounting and approvals</h2><p>As of <?= $e($asof) ?> · Configured cash is separate from Total Assets and does not imply unrestricted spendable money.</p><div class="budget-status-grid"><div><h3>Configured cash</h3><strong><?= $m($data['cash']??null) ?></strong><p><?= $e($data['cash_label']??'Reporting information unavailable') ?></p></div><div><h3>Outstanding advances</h3><strong><?= $m($data['outstanding_advances']??null) ?></strong><p>Released funds still to settle</p></div><div><h3>Approved monthly budget</h3><strong><?= $budget&&$budget['approval_state']==='no_approved_budget'?'No approved budget':$m($budget['budgeted']??null) ?></strong><p><?= $budget?$m($budget['spent']).' recognized actual through '.$e($budget['as_of']):'Budget actuals unavailable' ?></p><a href="budgets.php">View budgets and actuals</a></div><div><h3>Pending Management reviews</h3><strong><?= $data===null?'Unavailable':$e($data['pending_reviews']) ?></strong><p>Submitted items awaiting a decision</p><?php if(($_SESSION['Role']??'')==='Management'): ?><a href="management_reviews.php">Open review queue</a><?php else: ?><a href="budgets.php">View submitted budgets</a><?php endif; ?></div></div></section><?php
}
